/**
 * @classdesc Physically based transmissive node material that refracts the scene/backdrop
 * using the renderer's viewport mip texture. Implements Beer–Lambert attenuation,
 * roughness-driven smear, and optional chromatic dispersion, distortion, and blue-noise
 * dithering for stable sampling.
 *
 * Requires the WebGPU renderer entry points `three/webgpu` and TSL (`three/tsl`).
 *
 * An extension of the {@link MeshPhysicalNodeMaterial}, providing more advanced
 * transmission features.
 *
 * - Uses the node-material pipeline so you can override nodes like `iorNode`, `roughnessNode`, etc.
 * - Samples a screen-space capture of the scene (viewport buffer) for fast refraction.
 *
 * ```js
 * import { MeshTransmissionNodeMaterial } from '@three-blocks/core';
 * import * as THREE from 'three/webgpu';
 *
 * // Create transmission material
 * const mat = new MeshTransmissionNodeMaterial({
 *   color: new THREE.Color('#ffffff'),
 *   roughness: 0.2,
 *   thickness: 0.5,
 *   ior: 1.5,
 *   chromaticAberration: 0.4,
 *   anisotropicBlur: 0.1,
 *   distortion: 0.0,
 *   attenuationDistance: 0.5,
 *   attenuationColor: new THREE.Color('#ffffff')
 * });
 *
 * const geometry = new THREE.TorusKnotGeometry(1, 0.4, 128, 32);
 * const mesh = new THREE.Mesh(geometry, mat);
 * scene.add(mesh);
 * ```
 *
 * @extends THREE.MeshPhysicalNodeMaterial
 * @short MeshPhysicalNodeMaterial variant that samples the scene for transmission with chromatic aberration, distortion, and attenuation.
 * @demo docs/demos/mesh-transmission.html
 * @tags WebGPU, WebGL
 * @category Materials
 */
export class MeshTransmissionNodeMaterial {
    static get type(): string;
    /**
   * Constructs a new transmission node material.
   * Use `setValues(parameters)` to override properties; see property docs below.
   *
   * @param {Object} [parameters={}] Optional material parameters.
   * @param {number} [parameters.chromaticAberration=0.4] Strength of per-channel IOR dispersion.
   * @param {number} [parameters.anisotropicBlur=0.38] Minimum smear in the thickness direction for rough surfaces.
   * @param {number} [parameters.time=0] Time uniform used by temporal distortion.
     * @param {number} [parameters.distortion=0] Distortion amount applied to the refraction normal via noise; scales amplitude, 0 disables.
   * @param {number} [parameters.distortionScale=0] Distortion noise scale in world units.
   * @param {number} [parameters.temporalDistortion=0] Strength of time-based distortion animation.
   * @param {number} [parameters.ditherStrength=0.5] Blue-noise jitter strength for sampling stability.
   * @param {number} [parameters.ditherScale=128] Blue-noise tiling frequency (higher values tile smaller).
   * @param {THREE.Color|string|number} [parameters.color=0xffffff] Base albedo color.
   * @param {*} [parameters.viewportBuffer=null] Optional TSL sampler/texture node used to sample the scene; defaults to renderer viewport mip texture.
   */
    constructor(parameters?: {
        chromaticAberration?: number;
        anisotropicBlur?: number;
        time?: number;
        distortion?: number;
        distortionScale?: number;
        temporalDistortion?: number;
        ditherStrength?: number;
        ditherScale?: number;
        color?: THREE.Color | string | number;
        viewportBuffer?: any;
    });
    roughness: number;
    thickness: number;
    transmission: number;
    /**
     * This flag can be used for type testing.
 *
 * @type {boolean}
 * @readonly
 * @default true
 */
    readonly isMeshTransmissionNodeMaterial: boolean;
    /**
 * Render in a single pass. Yield better visual and performance results when sampling the backdrop texture.
 * @type {boolean}
 * @default true
 */
    forceSinglePass: boolean;
    /**
 * Strength of per-channel IOR dispersion. Higher values increase color fringing.
 * @type {number}
 * @default 0.4
 */
    chromaticAberration: number;
    /**
 * Optional map kept for API parity with other materials. Not sampled by this material.
 * @type {THREE.Texture|null}
 * @default null
 */
    transmissionMap: THREE.Texture | null;
    /**
 * Beer–Lambert attenuation distance; set to `Infinity` to disable attenuation.
 * @type {number}
 * @default Infinity
 */
    attenuationDistance: number;
    /**
 * Minimum smear in the thickness direction for rough surfaces.
 * @type {number}
 * @default 0.38
 */
    anisotropicBlur: number;
    /**
 * Time value used for temporal distortion animation.
 * @type {number}
 * @default 0
 */
    time: number;
    /**
 * Distortion amount applied to the perturbed refraction normal via noise. Values scale the noise amplitude; 0 disables the effect.
 * @type {number}
 * @default 0
 */
    distortion: number;
    /**
 * Distortion noise scale in world units.
 * @type {number}
 * @default 0
 */
    distortionScale: number;
    /**
 * Strength of time-based distortion animation.
 * @type {number}
 * @default 0
 */
    temporalDistortion: number;
    /**
 * Blue-noise jitter strength for sampling stability.
 * @type {number}
 * @default 0.5
 */
    ditherStrength: number;
    /**
 * Blue-noise tiling frequency (higher values tile smaller).
 * @type {number}
 * @default 128
 */
    ditherScale: number;
    /**
 * Optional TSL sampler/texture node used to sample the scene/backdrop.
 * If `null`, the renderer's viewport mip texture is used.
 * @type {*}
 * @default null
 */
    viewportBuffer: any;
    /**
 * Internal uniform node references.
 *
 * @type {Object}
 * @private
 */
    private _nodes;
    /**
     * Backdrop refraction node injected into the physical transmission pipeline.
     * @type {*}
    */
    backdropNode: any;
    /**
   * Attaches a debug UI for tuning transmission parameters.
   * Compatible with lil-gui, dat.gui, and Three.js Inspector.
   * @param {*} gui - GUI instance (e.g., lil-gui/dat.gui or renderer.inspector.createParameters()).
   * @returns {void}
   */
    attachGUI(gui: any): void;
    _debug: any;
    /**
   * Destroys and clears the debug folder if attached.
   * @returns {this}
   */
    disposeGUI(): this;
    /**
   * Disposes material resources and detaches any debug UI.
   * @override
   */
    override dispose(): void;
}
